def rolling_mean(values, window):
    if window > len(values):
        return []
    total = sum(values[:window])
    out = [total / window]
    for i in range(window, len(values)):
        # The new value comes in, the oldest leaves
        total += values[i] - values[i - window]
        out.append(total / window)
    return out
